package ch.piiwii.remote;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity{private final Map<String,Device>found=new LinkedHashMap<>();private final ExecutorService pool=Executors.newCachedThreadPool();private Spinner spinner;private TextView status;private ArrayAdapter<String>adapter;static class Device{String name,type,ip;Device(String n,String t,String i){name=n;type=t;ip=i;}public String toString(){return("TV".equals(type)?"📺 ":"🖥 ")+name;}}@Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);spinner=findViewById(R.id.devices);status=findViewById(R.id.status);adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new ArrayList<>());spinner.setAdapter(adapter);bind(R.id.refresh,v->discover());bindCmd(R.id.mute,"MUTE");bindCmd(R.id.volDown,"VOL_DOWN");bindCmd(R.id.volUp,"VOL_UP");bindCmd(R.id.prev,"PREV");bindCmd(R.id.playPause,"PLAY_PAUSE");bindCmd(R.id.next,"NEXT");discover();}private void bind(int id,View.OnClickListener l){findViewById(id).setOnClickListener(l);}private void bindCmd(int id,String c){bind(id,v->send(c));}private Device selected(){int p=spinner.getSelectedItemPosition();if(p<0||p>=found.size())return null;return new ArrayList<>(found.values()).get(p);}private void send(String c){Device d=selected();if(d==null){Toast.makeText(this,"Aucun appareil sélectionné",Toast.LENGTH_SHORT).show();return;}pool.execute(()->{try(DatagramSocket s=new DatagramSocket()){byte[]x=("PIIWII_CMD|"+c).getBytes(StandardCharsets.UTF_8);s.send(new DatagramPacket(x,x.length,InetAddress.getByName(d.ip),45455));runOnUiThread(()->status.setText("Commande envoyée à "+d.name));}catch(Exception e){runOnUiThread(()->status.setText("Erreur : "+e.getMessage()));}});}private void discover(){found.clear();adapter.clear();adapter.notifyDataSetChanged();status.setText("Recherche des appareils…");pool.execute(()->{try(DatagramSocket s=new DatagramSocket(45456)){s.setBroadcast(true);s.setSoTimeout(2200);byte[]q="PIIWII_DISCOVER".getBytes(StandardCharsets.UTF_8);s.send(new DatagramPacket(q,q.length,InetAddress.getByName("255.255.255.255"),45454));long end=System.currentTimeMillis()+2200;byte[]buf=new byte[512];while(System.currentTimeMillis()<end){try{DatagramPacket p=new DatagramPacket(buf,buf.length);s.receive(p);String m=new String(p.getData(),0,p.getLength(),StandardCharsets.UTF_8);String[]a=m.split("\\|");if(a.length>=3&&"PIIWII_REMOTE".equals(a[0])){String ip=p.getAddress().getHostAddress();found.put(ip,new Device(a[1],a[2],ip));runOnUiThread(this::refreshList);}}catch(SocketTimeoutException ignored){break;}}}catch(Exception e){runOnUiThread(()->status.setText("Recherche impossible : "+e.getMessage()));}runOnUiThread(()->{if(found.isEmpty())status.setText("Aucun appareil trouvé — vérifie le même Wi‑Fi");else status.setText(found.size()+" appareil(s) disponible(s)");});});}private void refreshList(){adapter.clear();for(Device d:found.values())adapter.add(d.toString());adapter.notifyDataSetChanged();}@Override protected void onDestroy(){super.onDestroy();pool.shutdownNow();}}
